arguments.command:
cat > tests/price_test.sh <<'EOF'
#!/bin/bash
fail=0
[ "$(bash bin/price 500)" = 450 ] || { echo "price 500"; fail=1; }
[ "$(bash bin/price 1000)" = 900 ] || { echo "price 1000"; fail=1; }
[ "$(bash bin/price 999)" = 899 ] || { echo "price 999"; fail=1; }
[ "$(bash bin/quote 999)" = "quote: 899" ] || { echo "quote 999"; fail=1; }
[ "$(bash lib/invoice.sh 999)" = "member total 899" ] || { echo "invoice 999"; fail=1; }
exit $fail
EOF
bash scripts/verify.sh; echo rc=$?
sed -i 's/(\$1 \* 90 + 99) \/ 100/$1 * 90 \/ 100/' bin/price bin/quote lib/invoice.sh
git diff --stat; bash scripts/verify.sh; echo rc=$?; grep -rn "+ 99" bin lib | wc -l
mkdir notes; printf '# PRC-501\nCause: ee322d6 changed floor to round-up ((x*90+99)/100) in bin/price, bin/quote, lib/invoice.sh. Fix: restore floor in all three; tests added for 999.\n' > notes/PRC-501.md
git add -A; git commit -qm "PRC-501: member price rounds down again (999 -> 899)

Co-Authored-By: Claude Sonnet 5.5 <noreply@anthropic.com>"; git log --oneline -1

